/**
 * Kho từ vựng bổ sung — phần 56a (Bài 56: N3). Do agent soạn; bai56.ts gom các phần lại.
 * Id mục: `b56-kho-NN-…`. Xem bai56.ts.
 *
 * Phần A = mục giới thiệu (b56-kho-00) + chủ đề 1–8 (phần B — kho56b.ts — chủ đề 9–16):
 *   1 thời gian · 2 phó từ mức độ · 3 phó từ thái độ + 擬態語・擬音語 · 4 động từ ghép + cặp tự/tha ·
 *   5 nhà cửa · 6 ăn uống · 7 mua sắm, tiền, thủ tục · 8 giao thông, du lịch, nơi chốn.
 * CHỐNG TRÙNG (09/11/2026): mọi từ đã đối chiếu (biểu ký + cách đọc) với danh sách ~3.100 từ đã dạy ở Bài 0–55
 * (bai/onTheData.ts › TU) — từ đã dạy thì BỎ, chỉ nhắc "(Bài N)" trong dòng `more` khi cần phân biệt.
 * Cấp JLPT trong `more` là ƯỚC LƯỢNG theo các bảng tham khảo phổ biến (JLPT không công bố danh sách chính thức).
 * Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Lesson } from '@/components/sach-hoc/types';

type Tu = Extract<Block, { t: 'vocab' }>['items'][number];
/** Một từ: biểu ký {漢字|かな} · loại từ · romaji · nghĩa · câu ví dụ · romaji câu · nghĩa câu · mở rộng (cụm đi kèm, phân biệt, cấp JLPT ước lượng). */
const T = (w: string, pos: string, ipa: string, vi: string, ex: string, exRo: string, exVi: string, more: string): Tu => ({
  w, pos, ipa, vi, ex, exVi, exRo, more,
});

type Mcq = Extract<Block, { t: 'mcq' }>['items'][number];
/**
 * Câu trắc nghiệm: viết đáp án ĐÚNG trước rồi các đáp án nhiễu; hàm đặt đáp án đúng vào một vị trí cố định suy
 * từ nội dung câu hỏi (không ngẫu nhiên — tiến độ lưu theo câu không đổi), để đáp án đúng không luôn ở ô đầu.
 */
const MQ = (q: string, dung: string, sai: string[], why: string): Mcq => {
  let h = 7;
  for (const ch of q) h = (h * 31 + (ch.codePointAt(0) ?? 0)) % 100003;
  const k = h % (sai.length + 1);
  return { q, options: [...sai.slice(0, k), dung, ...sai.slice(k)], correct: k, why };
};

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana (máy chấm đã tự bỏ dấu câu,
 * dấu cách). Phần tử đầu = dạng toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    let acc = [''];
    for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
    acc.forEach((a) => out.add(a));
  }
  return [...out];
};

